const PICKER_BASE = 'https://photospicker.googleapis.com/v1'

async function apiFetch(url, token, opts = {}) {
  const res = await fetch(url, {
    ...opts,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      ...(opts.headers || {}),
    },
  })
  if (!res.ok) {
    const body = await res.json().catch(() => ({}))
    const msg = body?.error?.message || body?.error?.status || `HTTP ${res.status}`
    const err = new Error(msg)
    err.status = res.status
    throw err
  }
  return res.json()
}

/**
 * Create a new Picker session.
 * Returns { id, pickerUri, pollingConfig, expireTime, mediaItemsSet }
 *
 * The Picker API accepts no content filters — `pickingConfig.maxItemCount` is
 * the only generally available input. There is no way to restrict a session to
 * an album; see the note on album browsing in the README.
 *
 * @param {string} token
 * @param {object} opts
 * @param {number} opts.maxItemCount - max items the user may pick (1–2000)
 */
export async function createPickerSession(token, { maxItemCount } = {}) {
  const body = maxItemCount
    ? { pickingConfig: { maxItemCount: String(maxItemCount) } }
    : {}
  return apiFetch(`${PICKER_BASE}/sessions`, token, {
    method: 'POST',
    body: JSON.stringify(body),
  })
}

/**
 * Get current state of a Picker session.
 * Returns { id, pickerUri, mediaItemsSet }
 */
export async function getPickerSession(token, sessionId) {
  return apiFetch(`${PICKER_BASE}/sessions/${encodeURIComponent(sessionId)}`, token)
}

/**
 * Delete a Picker session. Optional — sessions expire on their own.
 */
export async function deletePickerSession(token, sessionId) {
  return apiFetch(`${PICKER_BASE}/sessions/${encodeURIComponent(sessionId)}`, token, {
    method: 'DELETE',
  })
}

/**
 * Fetch the media items the user selected.
 * Call only after mediaItemsSet === true.
 */
export async function getPickerMediaItems(token, sessionId, pageSize = 100) {
  return apiFetch(
    `${PICKER_BASE}/mediaItems?sessionId=${encodeURIComponent(sessionId)}&pageSize=${pageSize}`,
    token
  )
}

/**
 * Open the picker popup. Returns the popup window handle.
 * Throws with code POPUP_BLOCKED if the browser blocked it.
 */
export function openPickerPopup(pickerUri, {
  popupFeatures = 'width=1000,height=700,menubar=no,toolbar=no',
} = {}) {
  const popup = window.open(pickerUri, 'gphotosPicker', popupFeatures)
  if (!popup) {
    throw Object.assign(
      new Error('Popup was blocked — allow popups for this site.'),
      { code: 'POPUP_BLOCKED' }
    )
  }
  return popup
}

/**
 * Poll a picker session until the user has confirmed a selection.
 * @returns {'done'|'closed'}
 */
async function waitForSelection(token, sessionId, popup, {
  pollInterval    = 2000,
  retryAfterClose = 5,
  retryDelay      = 2000,
  onStatus        = () => {},
} = {}) {
  return new Promise((resolve, reject) => {
    const poll = setInterval(async () => {
      try {
        if (popup.closed) {
          clearInterval(poll)
          onStatus('Window closed — checking for selection…')
          let remaining = retryAfterClose
          while (remaining-- > 0) {
            await new Promise(r => setTimeout(r, retryDelay))
            const s = await getPickerSession(token, sessionId)
            if (s.mediaItemsSet) { resolve('done'); return }
          }
          resolve('closed')
          return
        }
        const s = await getPickerSession(token, sessionId)
        if (s.mediaItemsSet) {
          clearInterval(poll)
          try { popup.close() } catch (_) {}
          resolve('done')
        }
      } catch (err) {
        clearInterval(poll)
        reject(err)
      }
    }, pollInterval)
  })
}

/**
 * Full flow: open the Google Photos picker, poll until the user confirms a
 * selection, and return the picked photos.
 *
 * @param {string} token - Google OAuth access token (photospicker.mediaitems.readonly)
 * @param {object} opts
 * @param {number}   opts.maxItemCount    - max items the user may pick (1–2000)
 * @param {number}   opts.pollInterval    - ms between session polls (default 2000)
 * @param {number}   opts.retryAfterClose - retries after the popup closes (default 5)
 * @param {number}   opts.retryDelay      - ms between those retries (default 2000)
 * @param {string}   opts.popupFeatures   - window.open features string
 * @param {function} opts.onStatus        - called with status string updates
 * @returns {Promise<Photo[]>} picked photos, or [] if cancelled
 */
export async function pickPhotos(token, opts = {}) {
  const {
    maxItemCount,
    popupFeatures = 'width=1000,height=700,menubar=no,toolbar=no',
    onStatus = () => {},
    ...pollOpts
  } = opts

  onStatus('Creating picker session…')
  const session = await createPickerSession(token, { maxItemCount })

  onStatus('Opening Google Photos…')
  const popup = openPickerPopup(session.pickerUri, { popupFeatures })
  try { popup.focus() } catch (_) {}

  onStatus('Waiting for photo selection…')
  const result = await waitForSelection(token, session.id, popup, { ...pollOpts, onStatus })
  if (result === 'closed') return []

  onStatus('Fetching selected photos…')
  const data = await getPickerMediaItems(token, session.id)
  return normalizeItems(data.mediaItems || [])
}

function normalizeItems(items) {
  return items.map(item => {
    const meta = item.mediaFile?.mediaFileMetadata
    return {
      id:          item.id,
      baseUrl:     item.mediaFile?.baseUrl || '',
      mimeType:    item.mediaFile?.mimeType || 'image/jpeg',
      filename:    item.mediaFile?.filename || '',
      width:       meta?.width  || null,
      height:      meta?.height || null,
      description: item.description || '',
      createTime:  item.createTime || null,
    }
  })
}
